dtsPropsFor.ConnectCard:
/** Connection lifecycle stage driving the status dot, label, and button fill. */
status: 'disconnected' | 'preparing' | 'connecting' | 'connected' | 'disconnecting' | 'failed';
/** Connected relay's display name (e.g. "silly-lemur"); null shows the auto-relay line. */
relayName: string | null;
/** Connected relay's node class (OFFICIAL/VOLUNTEER badge next to the name); null hides the badge. */
relayClass: 'foundation' | 'volunteer' | null;
isConnected: boolean;
isWorking: boolean;
onToggle: () => void;

dtsPropsFor.ConsolePanel:
/** "[HH:mm:ss] message" lines, newest last; empty shows the ready placeholder. */
logLines: string[];
/** Appended as an "! error" line in console-error red; null hides it. */
lastError: string | null;
/** Shows a dim "[mock native module]" notice (Debug screen, mock fallback). */
showMockNotice?: boolean;
style?: object;

dtsPropsFor.HomeIcon:
color: string;
size?: number;
strokeWidth?: number;

dtsPropsFor.InfoIcon:
color: string;
size?: number;
strokeWidth?: number;

dtsPropsFor.ListIcon:
color: string;
size?: number;
strokeWidth?: number;

dtsPropsFor.MapIcon:
color: string;
size?: number;
strokeWidth?: number;

dtsPropsFor.MapStatusChip:
directoryStatus: 'idle' | 'loading' | 'loaded' | 'failed';
regionCount: number;
/** Tapped in the failed / loaded-but-empty states. */
onRetry: () => void;
style?: object;

dtsPropsFor.OceanTelemetry:
regions: Array<{ countryCode: string; countryName: string; city: string | null; latitude: number; longitude: number; nodeCount: number; relays: Array<{ id: string; label: string | null; nodeClass: 'foundation' | 'volunteer' }> }>;
directoryStatus: 'idle' | 'loading' | 'loaded' | 'failed';
status: 'disconnected' | 'preparing' | 'connecting' | 'connected' | 'disconnecting' | 'failed';
/** Resolved exit location while connected; null shows the auto-relay target. */
relayLabel: string | null;
/** Friendly name of the connected relay, mirrored from native state (null while down). */
relayName: string | null;
/** Already-localized native error line, shown only in the failed state. */
lastError: string | null;
/** Epoch ms when the tunnel entered 'connected'; null while down. Drives the uptime clock. */
connectedAtMs: number | null;

dtsPropsFor.PowerIcon:
color: string;
size?: number;
strokeWidth?: number;

dtsPropsFor.RecentsSection:
/** Recent connections, newest first; entries lacking relayId/relayName (legacy) are hidden, and an empty result renders nothing at all. */
recents: Array<{ countryCode: string; relayId?: string; label: string; relayName?: string; latitude: number; longitude: number }>;
/** Relay ids the broker currently lists, or null while the directory has not loaded (no evidence either way — never a hint to hide). */
liveRelayIds: ReadonlySet<string> | null;
onPress: (relayId: string, countryCode: string) => void;

dtsPropsFor.RelayClassBadge:
/** 'foundation' renders the green OFFICIAL badge, 'volunteer' the orange one. */
nodeClass: 'foundation' | 'volunteer';
style?: object;

dtsPropsFor.RelayList:
regions: Array<{ countryCode: string; countryName: string; city: string | null; latitude: number; longitude: number; nodeCount: number; relays: Array<{ id: string; label: string | null; nodeClass: 'foundation' | 'volunteer' }> }>;
directoryStatus: 'idle' | 'loading' | 'loaded' | 'failed';
/** Connect to one specific relay (picked from an expanded location row). */
onRelayPress: (relayId: string, countryCode: string) => void;
/** Forced broker re-fetch: tap-to-retry on the empty panel AND pull-to-refresh on the list. */
onRetry: () => void;
/** True while a directory load is in flight; keeps the pull-to-refresh spinner up. */
refreshing?: boolean;
style?: object;

dtsPropsFor.SettingPanel:
title: string;
subtitle: string;
/** When set the row is pressable and shows a terminal-green chevron. */
onPress?: () => void;
/** Custom trailing element (replaces the chevron). */
trailing?: React.ReactNode;

dtsPropsFor.SlidersIcon:
color: string;
size?: number;
strokeWidth?: number;
